-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.canonical_path_malignant_events_v1_keyed
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.canonical_path_malignant_events_v1_keyed AS SELECT p.*, op.surgery_episode_id AS surgery_episode_uid_global, CASE  WHEN (((op.surgery_episode_id IS NULL) AND (p.surgery_date IS NOT NULL))) THEN (md5(((CAST(p.research_id AS VARCHAR) || '|') || CAST(p.surgery_date AS VARCHAR)))) ELSE NULL END AS surgery_episode_uid_fallback, COALESCE(CAST(op.surgery_episode_id AS VARCHAR), CASE  WHEN ((p.surgery_date IS NOT NULL)) THEN (md5(((CAST(p.research_id AS VARCHAR) || '|') || CAST(p.surgery_date AS VARCHAR)))) ELSE NULL END) AS surgery_episode_uid, CASE  WHEN ((op.surgery_episode_id IS NOT NULL)) THEN ('operative_match') WHEN ((p.surgery_date IS NOT NULL)) THEN ('md5_fallback') ELSE 'unknown_no_date' END AS surgery_episode_uid_source FROM main.canonical_path_malignant_events_v1 AS p LEFT JOIN main.canonical_operative_events_v1 AS op ON (((p.research_id = op.research_id) AND (p.surgery_date = CAST(op.resolved_surgery_date AS TIMESTAMP))));
